/**
 * Sound effects + background music. Assets are generated by `npm run generate:sounds` and can be
 * replaced with produced audio by dropping files with the same names into assets/sounds.
 * Every call is fail-safe: missing audio support never affects gameplay.
 */
import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';

import { getSettings } from '@/store/progressStore';

const SOUNDS = {
  tap: require('../../../assets/sounds/tap.wav'),
  pop: require('../../../assets/sounds/pop.wav'),
  button: require('../../../assets/sounds/button.wav'),
  success: require('../../../assets/sounds/success.wav'),
  failure: require('../../../assets/sounds/failure.wav'),
  streak: require('../../../assets/sounds/streak.wav'),
  levelStart: require('../../../assets/sounds/level-start.wav'),
  countdown: require('../../../assets/sounds/countdown.wav'),
  boss: require('../../../assets/sounds/boss.wav'),
  whoosh: require('../../../assets/sounds/whoosh.wav'),
} as const;

const MUSIC = require('../../../assets/sounds/music.wav');

export type SoundName = keyof typeof SOUNDS;

const VOLUME: Partial<Record<SoundName, number>> = { tap: 0.5, pop: 0.7, countdown: 0.6, whoosh: 0.6 };

class AudioService {
  private players = new Map<SoundName, AudioPlayer>();
  private music: AudioPlayer | null = null;
  private initialized = false;
  private musicWanted = false;

  async init() {
    if (this.initialized) return;
    this.initialized = true;
    try {
      await setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers' });
    } catch (error) {
      console.warn('[audio] setAudioMode failed', error);
    }
    for (const name of Object.keys(SOUNDS) as SoundName[]) {
      try {
        const player = createAudioPlayer(SOUNDS[name]);
        player.volume = VOLUME[name] ?? 0.9;
        this.players.set(name, player);
      } catch (error) {
        console.warn(`[audio] could not load ${name}`, error);
      }
    }
  }

  play(name: SoundName) {
    if (!getSettings().sound) return;
    const player = this.players.get(name);
    if (!player) return;
    try {
      player.seekTo(0).catch(() => undefined);
      player.play();
    } catch {
      // Audio is decoration; never let it interrupt the game.
    }
  }

  /** Starts or stops the music loop according to the settings. */
  syncMusic(wanted = this.musicWanted) {
    this.musicWanted = wanted;
    const enabled = wanted && getSettings().music;
    try {
      if (enabled) {
        if (!this.music) {
          this.music = createAudioPlayer(MUSIC);
          this.music.loop = true;
          this.music.volume = 0.25;
        }
        if (!this.music.playing) this.music.play();
      } else if (this.music?.playing) {
        this.music.pause();
      }
    } catch (error) {
      console.warn('[audio] music failed', error);
    }
  }
}

export const audio = new AudioService();
